contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public {
        uint before = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.sendMoney(address(0xdead), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert(reverted || afterCount == before);
    }

    receive() external payable {}
}

